cat > /tmp/rollup.jq <<'JQ'
def ckey: if (.customer // null) == null or .customer.id == null then "guest" else .customer.id end;
def linerev: ((.qty * .unit_cents * (100 - (.discount_pct // 0)) / 100) | floor);
def orev: ([(.items // [])[] | linerev] | add // 0);
def omonth: (.placed[0:7]);
(map(. + {__key: ckey, __rev: orev, __month: omonth})
 | sort_by(.__key)
 | group_by(.__key)
 | map(
   . as $g
   | ($g[0].__key) as $key
   | ([$g[] | select(.status == "paid")]) as $paid
   | ($paid | length) as $npaid
   | ([$paid[] | .__rev] | add // 0) as $rev
   | (if $key == "guest" then null else (($g | max_by(.placed) | .customer.name) // null) end) as $name
   | ($paid | group_by(.__month) | map({k: .[0].__month, v: ([.[].__rev] | add)}) | sort_by(.k) | from_entries) as $bym
   | ([$paid[] | (.items // [])[] | {sku, r: linerev}] | group_by(.sku) | map({sku: .[0].sku, r: ([.[].r] | add)}) | sort_by([-.r, .sku]) | .[0:3] | map(.sku)) as $top
   | {customer: $key, name: $name, paid_orders: $npaid, revenue_cents: $rev, by_month: $bym, top_skus: $top}
 )
 | sort_by(.customer)
)
JQ
jq -f /tmp/rollup.jq /home/eval/shop/data/orders.json

